import React, { useState, useEffect } from 'react';
import { MoreVertical, X, ClipboardCheck, ArrowRight, Instagram, Linkedin } from 'lucide-react';
import Button from './ui/Button';

interface HeaderProps {
  onOpenScreener: () => void;
  onOpenEarlyAccess: () => void;
  onNavigateHome: () => void;
  onNavigateAbout: () => void;
  onNavigateContact: () => void;
  currentPage: 'home' | 'about' | 'contact';
}

const Header: React.FC<HeaderProps> = ({ 
  onOpenScreener, 
  onOpenEarlyAccess, 
  onNavigateHome, 
  onNavigateAbout,
  onNavigateContact,
  currentPage 
}) => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 10);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navLinks = [
    { name: 'Home', href: '#', onClick: onNavigateHome, active: currentPage === 'home' },
    { name: 'About', href: '#', onClick: onNavigateAbout, active: currentPage === 'about' },
    { name: 'Contact', href: '#', onClick: onNavigateContact, active: currentPage === 'contact' },
    { name: 'Counselors', href: '#counselors', onClick: currentPage === 'home' ? undefined : onNavigateHome },
  ];

  const handleMobileClick = (onClick?: () => void) => {
    setIsMobileMenuOpen(false);
    if (onClick) onClick();
  };

  const instagramUrl = "https://www.instagram.com/yourmindlens?igsh=Y3hmMXlnZTB6cjRy";
  const linkedinUrl = "https://www.linkedin.com/company/ngcreationsofficial/";

  return (
    <header 
      className={`fixed top-0 left-0 right-0 z-[2000] transition-all duration-500 ${
        isScrolled ? 'bg-white/95 backdrop-blur-xl shadow-lg py-3' : 'bg-transparent py-5'
      }`}
    >
      <div className="container mx-auto px-6 flex items-center justify-between">
        <button 
          onClick={onNavigateHome} 
          className="flex items-center gap-2 group focus:outline-none relative z-[2100]"
        >
          <div className="w-9 h-9 flex items-center justify-center bg-calm-blue rounded-xl text-white shadow-lg group-hover:scale-110 transition-transform">
             <div className="w-2 h-2 bg-white rounded-full"></div>
          </div>
          <span className="text-xl font-bold tracking-tight text-slate-900">MindLens</span>
        </button>

        {/* Desktop & Tablet Nav */}
        <nav className="hidden lg:flex items-center space-x-8">
          <div className="flex items-center space-x-6 mr-4 border-r border-slate-200 pr-8">
            {navLinks.map((link) => (
              <a 
                key={link.name} 
                href={link.href}
                onClick={(e) => {
                  if(link.onClick) {
                    e.preventDefault();
                    link.onClick();
                  }
                }}
                className={`text-sm font-bold transition-colors ${
                  link.active ? 'text-calm-blue' : 'text-slate-400 hover:text-slate-900'
                }`}
              >
                {link.name}
              </a>
            ))}
          </div>

          <div className="flex items-center gap-6">
            <div className="flex items-center gap-4 text-slate-400">
              <a 
                href={instagramUrl} 
                target="_blank" 
                rel="noopener noreferrer" 
                className="hover:text-pink-600 transition-colors"
                aria-label="Instagram"
              >
                <Instagram size={20} />
              </a>
              <a 
                href={linkedinUrl} 
                target="_blank" 
                rel="noopener noreferrer" 
                className="hover:text-blue-700 transition-colors"
                aria-label="LinkedIn"
              >
                <Linkedin size={20} />
              </a>
            </div>
            <div className="flex gap-3">
              <Button variant="outline" size="sm" onClick={onOpenScreener} className="px-4 py-2">Assessment</Button>
              <Button variant="primary" size="sm" onClick={onOpenEarlyAccess} className="px-4 py-2">Waitlist</Button>
            </div>
          </div>
        </nav>

        {/* Mobile Toggle */}
        <button 
          className="lg:hidden w-14 h-14 flex items-center justify-center rounded-2xl bg-white border border-slate-100 shadow-md active:scale-90 transition-all text-slate-900 relative z-[2100]"
          onClick={() => setIsMobileMenuOpen(true)}
          aria-label="Open menu"
        >
          <MoreVertical size={28} strokeWidth={2.5} />
        </button>
      </div>

      {/* Mobile Menu */}
      {isMobileMenuOpen && (
        <div className="fixed inset-0 z-[5000] lg:hidden animate-in fade-in duration-300">
          <div 
            className="absolute inset-0 bg-slate-900/60 backdrop-blur-md"
            onClick={() => setIsMobileMenuOpen(false)}
          />

          <div className="absolute inset-0 flex items-center justify-center p-6">
            <div className="w-full max-w-sm bg-white rounded-[40px] p-8 shadow-2xl relative animate-in zoom-in slide-in-from-bottom-10 duration-500">
              <div className="flex items-center justify-between mb-8">
                <span className="font-black text-xl text-slate-900">Navigation</span>
                <button 
                  onClick={() => setIsMobileMenuOpen(false)}
                  className="w-12 h-12 flex items-center justify-center rounded-2xl bg-slate-100 text-slate-500 hover:text-slate-900"
                >
                  <X size={24} />
                </button>
              </div>

              <div className="space-y-3">
                {navLinks.map((link) => (
                  <button 
                    key={link.name}
                    onClick={() => handleMobileClick(link.onClick)}
                    className={`w-full text-left p-5 rounded-3xl flex items-center justify-between font-bold text-lg transition-all ${
