              <div className="mt-8 pt-8 border-t border-slate-100">
                <p className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-5">Connect with us</p>
                <div className="grid grid-cols-2 gap-4">
                   <a 
                    href={instagramUrl} 
                    target="_blank" 
                    rel="noopener noreferrer"
                    className="flex flex-col items-center justify-center gap-3 p-6 bg-pink-50 rounded-3xl border border-pink-100 text-pink-600 hover:bg-pink-100 transition-colors pointer-events-auto cursor-pointer"
                   >
                     <Instagram size={24} />
                     <span className="text-xs font-black">Instagram</span>
                   </a>
                   <a 
                    href={linkedinUrl} 
                    target="_blank" 
                    rel="noopener noreferrer"
                    className="flex flex-col items-center justify-center gap-3 p-6 bg-blue-50 rounded-3xl border border-blue-100 text-blue-700 hover:bg-blue-100 transition-colors pointer-events-auto cursor-pointer"
                   >
                     <Linkedin size={24} />
                     <span className="text-xs font-black">LinkedIn</span>
                   </a>
                </div>
              </div>

              <div className="mt-8">
                 <Button variant="primary" className="w-full py-5 rounded-3xl" onClick={() => handleMobileClick(onOpenEarlyAccess)}>
                   Join the Waitlist
                 </Button>
              </div>
            </div>
          </div>
        </div>
      )}
    </header>
  );
};

export default Header;

