          <div className="mt-12">
            <h5 className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-6">Booking Summary</h5>

            <div className="space-y-8">
              <div className="flex items-start gap-4">
                <div className="w-10 h-10 rounded-xl bg-white shadow-sm flex items-center justify-center text-calm-blue">
                  <Video size={18} />
                </div>
                <div>
                  <div className="text-xs font-black text-slate-900 uppercase">Service</div>
                  <div className="text-sm font-medium text-slate-500">{selectedService?.title || 'Not selected'}</div>
                </div>
              </div>

              <div className="flex items-start gap-4">
                <div className="w-10 h-10 rounded-xl bg-white shadow-sm flex items-center justify-center text-calm-blue">
                  <Calendar size={18} />
