                </div>
              </div>

              <div className="flex items-start gap-4">
                <div className="w-10 h-10 rounded-xl bg-white shadow-sm flex items-center justify-center text-calm-blue">
                  <CreditCard size={18} />
                </div>
                <div>
                  <div className="text-xs font-black text-slate-900 uppercase">Total Fee</div>
