            <div className="mt-20 p-6 bg-white rounded-3xl border border-slate-100 shadow-sm relative overflow-hidden group">
               <div className="absolute top-0 right-0 p-2 opacity-10 group-hover:scale-110 transition-transform">
                 <Info size={40} className="text-calm-blue" />
               </div>
               <p className="text-[10px] font-bold text-slate-400 leading-relaxed relative z-10">
                 All sessions are HIPAA-compliant. Cancellations within 24 hours of session time are non-refundable.
               </p>
