  );
};

export default BookingModal;

import React, { useState } from 'react';
import { X, Send, ShieldCheck, Heart, User, CheckCircle2, AlertCircle, MessageSquare } from 'lucide-react';
import Button from './ui/Button';

interface MessagingModalProps {
  isOpen: boolean;
  onClose: () => void;
}

const tags = ['Session Inquiry', 'Follow-up', 'Resource Request', 'Clinical Feedback', 'Other'];
const urgencies = [
  { label: 'Normal', desc: 'Standard response (24h)', color: 'bg-slate-100 text-slate-600' },
  { label: 'Urgent', desc: 'Prioritized (4-8h)', color: 'bg-orange-50 text-orange-600 border-orange-100' }
];

const MessagingModal: React.FC<MessagingModalProps> = ({ isOpen, onClose }) => {
  const [selectedTag, setSelectedTag] = useState('Session Inquiry');
  const [urgency, setUrgency] = useState('Normal');
  const [replyMethod, setReplyMethod] = useState('Email');
  const [message, setMessage] = useState('');
  const [isSent, setIsSent] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  if (!isOpen) return null;

  const handleSend = () => {
    if (!message.trim()) return;
    setIsLoading(true);
    setTimeout(() => {
      setIsLoading(false);
      setIsSent(true);
    }, 1500);
  };

  const handleClose = () => {
    onClose();
    setTimeout(() => {
      setIsSent(false);
      setMessage('');
      setSelectedTag('Session Inquiry');
      setUrgency('Normal');
    }, 500);
  };

  return (
    <div className="fixed inset-0 z-[5000] flex items-center justify-center p-4 sm:p-6 bg-slate-900/60 backdrop-blur-md animate-in fade-in duration-300">
      <div className="bg-white w-full max-w-xl rounded-[32px] sm:rounded-[40px] shadow-2xl overflow-hidden relative flex flex-col max-h-[95vh] animate-in zoom-in slide-in-from-bottom-8 duration-500">

        {/* Header */}
        <div className="p-6 sm:p-8 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 rounded-2xl overflow-hidden shadow-md border-2 border-white">
              <img src="https://drive.google.com/thumbnail?id=1RT3NZdXzPcur9x7nuxtj_X987b8sNEKN&sz=w100" className="w-full h-full object-cover" alt="Nidhi Gadoya" />
            </div>
            <div>
              <h3 className="font-black text-xl text-slate-900 leading-tight">Direct Messaging</h3>
              <div className="flex items-center gap-1.5 text-[9px] font-black text-green-600 uppercase tracking-widest">
                <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse" /> Protected Clinical Line
              </div>
            </div>
          </div>
          <button onClick={handleClose} className="w-10 h-10 flex items-center justify-center rounded-xl bg-white shadow-sm border border-slate-100 text-slate-400 hover:text-slate-900 transition-colors">
            <X size={20} />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-6 sm:p-10 space-y-10">
          {!isSent ? (
            <>
              {/* Category & Urgency */}
              <div className="grid sm:grid-cols-2 gap-8">
                <div className="space-y-4">
                  <label className="text-[10px] font-black uppercase text-slate-400 ml-1 tracking-wider">Message Type</label>
                  <div className="flex flex-wrap gap-2">
                    {tags.map(t => (
                      <button 
                        key={t}
                        onClick={() => setSelectedTag(t)}
                        className={`px-3 py-2 rounded-xl text-[10px] font-bold transition-all ${
                          selectedTag === t ? 'bg-calm-blue text-white shadow-md' : 'bg-slate-100 text-slate-500 hover:bg-slate-200'
                        }`}
                      >
                        {t}
                      </button>
                    ))}
                  </div>
                </div>

                <div className="space-y-4">
                  <label className="text-[10px] font-black uppercase text-slate-400 ml-1 tracking-wider">Priority Level</label>
                  <div className="flex gap-2">
                    {urgencies.map(u => (
                      <button 
                        key={u.label}
                        onClick={() => setUrgency(u.label)}
                        className={`flex-1 p-2 rounded-xl border transition-all text-center ${
                          urgency === u.label 
                          ? (u.label === 'Urgent' ? 'bg-orange-50 border-orange-200 text-orange-600 shadow-sm' : 'bg-calm-blue border-calm-blue text-white shadow-sm')
                          : 'bg-slate-50 border-slate-100 text-slate-400 hover:border-slate-200'
                        }`}
                      >
                        <div className="text-[10px] font-black uppercase">{u.label}</div>
                        <div className={`text-[8px] font-bold ${urgency === u.label ? (u.label === 'Urgent' ? 'text-orange-400' : 'text-blue-200') : 'text-slate-300'}`}>{u.desc}</div>
                      </button>
                    ))}
                  </div>
                </div>
              </div>

              {/* Message Input */}
              <div className="space-y-4">
                <div className="flex justify-between items-end ml-1">
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-wider">Your clinical inquiry</label>
                  <span className={`text-[10px] font-bold ${message.length > 500 ? 'text-red-400' : 'text-slate-300'}`}>{message.length}/500</span>
                </div>
                <div className="relative group">
                  <textarea 
                    rows={6}
                    maxLength={500}
                    placeholder="Share your thoughts or questions safely here..."
                    className="w-full p-6 bg-slate-50 border border-slate-100 rounded-[28px] outline-none focus:border-calm-blue focus:bg-white transition-all resize-none shadow-inner text-sm leading-relaxed"
                    value={message}
                    onChange={e => setMessage(e.target.value)}
                  />
                  <div className="absolute bottom-4 right-6 flex items-center gap-2 text-[9px] text-slate-400 font-bold uppercase tracking-tighter">
                    <ShieldCheck size={12} className="text-green-500" /> AES-256 Encrypted
                  </div>
                </div>
              </div>

              {/* Reply Preferences */}
              <div className="space-y-4">
                 <label className="text-[10px] font-black uppercase text-slate-400 ml-1 tracking-wider">How should Nidhi reply?</label>
                 <div className="grid grid-cols-2 gap-3">
                    {['Email', 'WhatsApp'].map(method => (
                      <button 
                        key={method}
                        onClick={() => setReplyMethod(method)}
                        className={`p-3 rounded-2xl border-2 font-bold text-xs transition-all ${
                          replyMethod === method ? 'border-calm-blue bg-blue-50/50 text-calm-blue' : 'border-slate-100 text-slate-400'
                        }`}
                      >
                        via {method}
                      </button>
                    ))}
                 </div>
              </div>

              <div className="p-6 bg-blue-50/50 rounded-[28px] border border-blue-100 flex gap-4">
                 <div className="shrink-0 w-10 h-10 bg-white rounded-xl flex items-center justify-center text-calm-blue shadow-sm">
                   <AlertCircle size={20} />
                 </div>
                 <p className="text-[10px] text-blue-800 leading-relaxed font-bold">
                   Non-emergency channel only. If you are experiencing a crisis, please call emergency services immediately.
                 </p>
              </div>

              <Button 
                className="w-full py-5 rounded-3xl gap-2 shadow-xl shadow-calm-blue/20"
                onClick={handleSend}
                disabled={!message.trim() || isLoading}
              >
                {isLoading ? <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white"></div> : <><Send size={20} /> Send Securely</>}
              </Button>
            </>
          ) : (
            <div className="text-center py-10 animate-in zoom-in-95 duration-500">
              <div className="w-24 h-24 bg-blue-50 text-calm-blue rounded-full flex items-center justify-center mx-auto mb-8 shadow-inner ring-8 ring-blue-50/50">
                <CheckCircle2 size={48} />
              </div>
              <h4 className="text-3xl font-black text-slate-900 mb-4 tracking-tight">Transmission Successful</h4>
              <p className="text-slate-500 mb-10 text-lg leading-relaxed max-w-sm mx-auto">
                Your clinical note is now in Dr. Nidhi's secure vault. She typically responds via <span className="font-bold text-slate-900">{replyMethod}</span> within <span className="font-bold text-slate-900">{urgency === 'Urgent' ? '8 hours' : '24 hours'}</span>.
              </p>
              <div className="flex flex-col gap-3">
                 <Button variant="outline" className="w-full py-4 rounded-2xl gap-2" onClick={handleClose}>
                   <MessageSquare size={18} /> Close Channel
                 </Button>
              </div>
            </div>
          )}
        </div>

        {/* Branding Footer */}
        <div className="p-4 bg-slate-50 border-t border-slate-100 flex items-center justify-center gap-8">
           <div className="flex items-center gap-1.5 text-[8px] font-black uppercase text-slate-400 tracking-widest">
             <ShieldCheck size={10}/> Data Sovereignty
           </div>
           <div className="flex items-center gap-1.5 text-[8px] font-black uppercase text-slate-400 tracking-widest">
             <User size={10}/> Private Vault
           </div>
        </div>
      </div>
    </div>
  );
};

export default MessagingModal;

import React, { useState } from 'react';
import { X, ChevronRight, Calendar, Clock, Video, CheckCircle2, ArrowLeft, CreditCard, Download, CalendarPlus, Info, Hash, Mail, Shield } from 'lucide-react';
import Button from './ui/Button';

interface BookingModalProps {
  isOpen: boolean;
  onClose: () => void;
}

type Step = 'service' | 'datetime' | 'details' | 'success';

const services = [
  { id: 'individual', title: 'Individual Therapy', duration: '50 mins', price: '$80', icon: <Video size={24} />, description: 'One-on-one session using CBT/ACT techniques.' },
  { id: 'couple', title: 'Couple Counseling', duration: '75 mins', price: '$120', icon: <Video size={24} />, description: 'Improving communication and relationship dynamics.' },
  { id: 'diagnostic', title: 'Clinical Review', duration: '30 mins', price: '$50', icon: <Video size={24} />, description: 'Expert analysis of your MindLens assessments.' },
];

const timeSlots = [
  '09:00 AM', '10:30 AM', '01:00 PM', '02:30 PM', '04:00 PM', '05:30 PM'
];

const clinicalCategories = [
  'Anxiety & Stress', 'Depression', 'Work-Life Balance', 'Relationship Issues', 'Self-Esteem', 'Other'
];

const BookingModal: React.FC<BookingModalProps> = ({ isOpen, onClose }) => {
  const [step, setStep] = useState<Step>('service');
  const [selectedService, setSelectedService] = useState<typeof services[0] | null>(null);
  const [selectedDate, setSelectedDate] = useState<string>('');
  const [selectedTime, setSelectedTime] = useState<string>('');
  const [formData, setFormData] = useState({ name: '', email: '', category: 'Anxiety & Stress', note: '' });
  const [confirmationId, setConfirmationId] = useState('');

  if (!isOpen) return null;

  const generateConfirmationId = () => {
    const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
    let result = 'ML-';
    for (let i = 0; i < 6; i++) {
      result += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    return result;
  };

  const handleNext = () => {
    if (step === 'service') setStep('datetime');
    else if (step === 'datetime') setStep('details');
    else if (step === 'details') {
      setConfirmationId(generateConfirmationId());
      setStep('success');
    }
  };

  const handleBack = () => {
    if (step === 'datetime') setStep('service');
    else if (step === 'details') setStep('datetime');
  };

  const reset = () => {
    setStep('service');
    setSelectedService(null);
    setSelectedDate('');
    setSelectedTime('');
    setFormData({ name: '', email: '', category: 'Anxiety & Stress', note: '' });
    setConfirmationId('');
  };

  const handleClose = () => {
    onClose();
    setTimeout(reset, 500);
  };

  return (
    <div className="fixed inset-0 z-[5000] flex items-center justify-center p-4 sm:p-6 bg-slate-900/60 backdrop-blur-md animate-in fade-in duration-300">
      <div className="bg-white w-full max-w-4xl rounded-[32px] sm:rounded-[40px] shadow-2xl overflow-hidden relative flex flex-col lg:flex-row max-h-[90vh] animate-in zoom-in slide-in-from-bottom-8 duration-500">

        {/* Left Section: Main Flow */}
        <div className="flex-1 flex flex-col bg-white overflow-hidden">
          {/* Header */}
          <div className="p-6 sm:p-8 border-b border-slate-100 flex items-center justify-between bg-white">
            <div className="flex items-center gap-4">
              {step !== 'service' && step !== 'success' && (
                <button onClick={handleBack} className="p-2 hover:bg-slate-50 rounded-xl text-slate-400 hover:text-slate-900 transition-all">
                  <ArrowLeft size={20} />
                </button>
              )}
              <div>
                <h3 className="font-black text-xl text-slate-900">Book Session</h3>
                <p className="text-[10px] font-black text-calm-blue uppercase tracking-widest">Clinical Portal v2.0</p>
              </div>
            </div>
            <button onClick={handleClose} className="lg:hidden w-10 h-10 flex items-center justify-center rounded-xl bg-slate-50 text-slate-400">
              <X size={20} />
            </button>
          </div>

          {/* Progress Bar */}
          {step !== 'success' && (
            <div className="h-1 w-full bg-slate-100">
              <div 
                className="h-full bg-calm-blue transition-all duration-500" 
                style={{ width: step === 'service' ? '33%' : step === 'datetime' ? '66%' : '100%' }}
              />
            </div>
          )}

          {/* Content Area */}
          <div className="flex-1 overflow-y-auto p-6 sm:p-10">
            {step === 'service' && (
              <div className="space-y-6">
                <div className="mb-8">
                  <h4 className="text-2xl font-bold text-slate-900 mb-2">How can we help?</h4>
                  <p className="text-slate-500">Select the therapeutic approach that best fits your current needs.</p>
                </div>
                <div className="grid gap-4">
                  {services.map(s => (
                    <button 
                      key={s.id}
                      onClick={() => { setSelectedService(s); handleNext(); }}
                      className={`p-6 rounded-[28px] border-2 text-left flex items-center justify-between transition-all group ${
                        selectedService?.id === s.id ? 'border-calm-blue bg-blue-50/50 shadow-lg' : 'border-slate-100 hover:border-blue-200 bg-white'
                      }`}
                    >
                      <div className="flex items-center gap-5">
                        <div className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-colors ${
                          selectedService?.id === s.id ? 'bg-calm-blue text-white' : 'bg-slate-50 text-slate-400 group-hover:text-calm-blue group-hover:bg-white group-hover:shadow-sm'
                        }`}>
                          {s.icon}
                        </div>
                        <div>
                          <div className="font-bold text-slate-900 text-lg">{s.title}</div>
                          <p className="text-xs text-slate-500 max-w-xs">{s.description}</p>
                        </div>
                      </div>
                      <div className="text-right">
                        <div className="font-black text-calm-blue text-lg">{s.price}</div>
                        <div className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">{s.duration}</div>
                      </div>
                    </button>
                  ))}
                </div>
              </div>
            )}

            {step === 'datetime' && (
              <div className="space-y-8 animate-in fade-in slide-in-from-right-4">
                <div className="mb-2">
                  <h4 className="text-2xl font-bold text-slate-900 mb-2">Pick a slot</h4>
                  <p className="text-slate-500">All times are shown in your local timezone.</p>
                </div>

                <div className="grid md:grid-cols-2 gap-8">
                  <div className="space-y-3">
                    <label className="text-[10px] font-black uppercase text-slate-400 ml-1">1. Select Date</label>
                    <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100 flex items-center gap-3">
                      <Calendar size={20} className="text-calm-blue" />
                      <input 
                        type="date" 
                        className="bg-transparent font-bold text-slate-900 outline-none flex-1 cursor-pointer"
                        min={new Date().toISOString().split('T')[0]}
                        onChange={(e) => setSelectedDate(e.target.value)}
                        value={selectedDate}
                      />
                    </div>
                  </div>

                  <div className="space-y-3">
                    <label className="text-[10px] font-black uppercase text-slate-400 ml-1">2. Select Time</label>
                    <div className="grid grid-cols-2 gap-2">
                      {timeSlots.map(t => (
                        <button 
                          key={t}
                          onClick={() => setSelectedTime(t)}
                          className={`p-3 rounded-xl font-bold text-xs transition-all ${
                            selectedTime === t ? 'bg-calm-blue text-white shadow-lg' : 'bg-white border border-slate-100 text-slate-600 hover:border-calm-blue/30'
                          }`}
                        >
                          {t}
                        </button>
                      ))}
                    </div>
                  </div>
                </div>

                <Button 
                  disabled={!selectedDate || !selectedTime}
                  className="w-full py-5 rounded-3xl mt-4"
                  onClick={handleNext}
                >
                  Confirm Time & Continue
                </Button>
              </div>
            )}

            {step === 'details' && (
              <div className="space-y-8 animate-in fade-in slide-in-from-right-4">
                <div className="">
                  <h4 className="text-2xl font-bold text-slate-900 mb-2">Finalize Details</h4>
                  <p className="text-slate-500">We prioritize your privacy above all else.</p>
                </div>

                <div className="grid md:grid-cols-2 gap-6">
                  <div className="space-y-1">
                    <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Full Name</label>
                    <input 
                      type="text" 
                      placeholder="Enter your name"
                      className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl outline-none focus:border-calm-blue transition-all"
                      value={formData.name}
                      onChange={e => setFormData({...formData, name: e.target.value})}
                    />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Primary Concern</label>
                    <select 
                      className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl outline-none focus:border-calm-blue transition-all appearance-none cursor-pointer"
                      value={formData.category}
                      onChange={e => setFormData({...formData, category: e.target.value})}
                    >
                      {clinicalCategories.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                  </div>
                </div>

                <div className="space-y-1">
                  <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Intake Note (Optional)</label>
                  <textarea 
                    rows={4}
                    placeholder="Briefly describe what's on your mind. This helps Nidhi prepare for your session."
                    className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl outline-none focus:border-calm-blue transition-all resize-none shadow-inner"
                    value={formData.note}
                    onChange={e => setFormData({...formData, note: e.target.value})}
                  ></textarea>
                </div>

                <Button 
                  disabled={!formData.name}
                  className="w-full py-5 rounded-3xl gap-2 shadow-xl shadow-calm-blue/20"
                  onClick={handleNext}
                >
                  <CreditCard size={20} /> Complete Booking
                </Button>
              </div>
            )}

            {step === 'success' && (
              <div className="text-center py-6 sm:py-10 animate-in zoom-in-95 duration-500">
                <div className="w-20 h-20 sm:w-24 sm:h-24 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-6 sm:mb-8 animate-bounce shadow-inner">
                  <CheckCircle2 size={48} />
                </div>
                <h4 className="text-3xl sm:text-4xl font-black text-slate-900 mb-2">Session Confirmed!</h4>

                <div className="inline-flex items-center gap-2 px-4 py-2 bg-slate-100 rounded-2xl mb-6 sm:mb-8">
                  <Hash size={16} className="text-slate-400" />
                  <span className="text-sm font-black text-slate-600 tracking-wider">Confirmation: {confirmationId}</span>
                </div>

                <div className="max-w-md mx-auto space-y-6 mb-10">
                  <p className="text-slate-500 text-base sm:text-lg leading-relaxed">
                    Thank you, <span className="font-bold text-slate-900">{formData.name.split(' ')[0]}</span>. Your booking is finalized. Please follow these next steps:
                  </p>

                  <div className="grid gap-3 text-left">
