                          Regenerate Visual
                        </Button>
                      </div>
                    </>
                  )}
                </div>
              </div>
            </div>
          </Reveal>

          {/* Future Therapy Section */}
          <Reveal>
            <div className="grid lg:grid-cols-2 gap-12 lg:gap-24 items-center">
              <div className="order-2 lg:order-1 relative group perspective-1000">
