            </div>

            <div className="flex items-start gap-6">
              <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shadow-sm ${selectedDate ? 'bg-calm-blue text-white' : 'bg-white text-slate-200'}`}>
                <Calendar size={22} />
