                            selectedService?.id === s.id ? 'border-calm-blue bg-blue-50/50 shadow-xl' : 'border-slate-100 hover:border-blue-200 bg-white'
                          }`}
                        >
                          <div className="flex items-center gap-4 sm:gap-6 pointer-events-none">
