                          </div>
                        </button>
                      ))}
                    </div>
                  </div>
                )}

                {step === 'datetime' && (
                  <div className="space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-20 lg:pb-0">
                    <div>
                      <h4 className="text-2xl sm:text-3xl font-black text-slate-900 mb-2">Select Date & Time</h4>
