                <div className="flex items-center gap-2">
                  <span className={`w-1.5 h-1.5 rounded-full ${isProcessing ? 'bg-orange-400 animate-spin' : 'bg-green-500 animate-pulse'}`}></span>
                  <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Clinical Protocol RC-12</p>
                </div>
              </div>
            </div>
            {!isProcessing && (
              <button onClick={handleClose} className="w-11 h-11 flex items-center justify-center rounded-xl bg-slate-50 text-slate-400 hover:text-slate-900 transition-all active:scale-90">
                <X size={22} />
              </button>
            )}
          </div>

          <div className="flex-1 overflow-y-auto p-6 sm:p-10 lg:p-14 pb-12 sm:pb-10 custom-scrollbar">
