                  <div className="absolute inset-0 flex items-center justify-center">
                    <ShieldCheck size={32} className="text-calm-blue/30" />
                  </div>
                </div>
                <div className="text-center">
                  <h4 className="text-2xl font-black text-slate-900 mb-2">{processingStatus}</h4>
                  <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest">Verifying Clinical Eligibility</p>
                </div>
              </div>
            ) : (
              <>
                {step === 'service' && (
