          {/* Persistent Action Footer */}
          {step !== 'success' && !isProcessing && (
            <div className="p-6 sm:p-8 bg-white border-t border-slate-100 flex flex-col sm:flex-row gap-4">
              <Button 
                disabled={step === 'service' ? !selectedService : step === 'datetime' ? (!selectedDate || !selectedTime) : !formData.name}
                className="w-full py-5 rounded-3xl gap-3 shadow-xl shadow-calm-blue/20 text-lg font-black"
                onClick={handleNext}
              >
                {step === 'details' ? <><CreditCard size={22} /> Authorize {selectedService?.price}</> : <>Continue to Next Step <ChevronRight size={22} /></>}
              </Button>
            </div>
          )}
        </div>

        {/* Desktop Sidebar: Clinical Summary */}
        <div className="hidden lg:flex w-96 bg-slate-50 border-l border-slate-100 flex-col p-12 shrink-0">
          <div className="space-y-12">
