              <div className="flex items-start gap-4">
                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shadow-md ${selectedService ? 'bg-calm-blue text-white' : 'bg-white text-slate-200'}`}>
                  {selectedService?.icon || <Video size={20} />}
                </div>
                <div>
                  <div className="font-black text-slate-900 leading-tight">{selectedService?.title || 'Selecting...'}</div>
                  <div className="text-[10px] text-slate-400 font-bold mt-1">{selectedService?.duration || 'Time TBD'}</div>
                </div>
              </div>
            </div>

            <div className={`transition-all duration-500 delay-100 ${selectedDate ? 'opacity-100 translate-x-0' : 'opacity-30 translate-x-4'}`}>
              <div className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-3">Appointment Window</div>
              <div className="flex items-start gap-4">
                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shadow-md ${selectedDate ? 'bg-calm-blue text-white' : 'bg-white text-slate-200'}`}>
                  <Clock size={22} />
                </div>
                <div>
                  <div className="font-black text-slate-900 leading-tight">{selectedDate ? new Date(selectedDate).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) : 'Pending Date'}</div>
                  <div className="text-[10px] text-calm-blue font-black mt-1 uppercase tracking-widest">{selectedTime || 'Select Time Slot'}</div>
                </div>
              </div>
            </div>

            <div className="pt-12 border-t border-slate-200">
               <div className="flex justify-between items-center mb-4">
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Clinical Fee</span>
                  <span className="text-4xl font-black text-calm-blue">{selectedService?.price || '$0'}</span>
               </div>
               <div className="flex items-center gap-2 text-[8px] font-black text-slate-400 uppercase tracking-[0.2em]">
                 <Shield size={12} className="text-green-500" /> End-to-End Encryption Active
               </div>
            </div>

            <div className="mt-12 space-y-4">
               <div className="p-5 bg-white rounded-3xl border border-slate-200 shadow-sm flex gap-4 items-start">
                  <Info size={18} className="text-calm-blue shrink-0 mt-0.5" />
                  <p className="text-[10px] text-slate-500 font-medium leading-relaxed">You will receive an intake form via email. Please complete it 2 hours before the session.</p>
               </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

