                    <div className="mt-12 flex flex-col gap-4 w-full max-w-sm">
                       <Button variant="primary" className="py-5 rounded-2xl shadow-xl shadow-calm-blue/20" onClick={handleClose}>Done</Button>
                       <button className="text-xs font-black uppercase tracking-widest text-slate-400 hover:text-slate-600 flex items-center justify-center gap-2">
