                onClick={handleNext}
              >
                {step === 'details' ? <><CreditCard size={22} /> Authorize {selectedService?.price}</> : <>Continue to Next Step <ChevronRight size={22} /></>}
              </Button>
            </div>
          )}
        </div>

        {/* Desktop Sidebar: Clinical Summary */}
        <div className="hidden lg:flex w-96 bg-slate-50 border-l border-slate-100 flex-col p-12 shrink-0">
          <div className="space-y-12">
            <h5 className="text-[11px] font-black uppercase text-slate-400 tracking-[0.2em]">Session Cart</h5>

            <div className={`transition-all duration-500 ${selectedService ? 'opacity-100 translate-x-0' : 'opacity-30 translate-x-4'}`}>
              <div className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-3">Therapeutic Focus</div>
              <div className="flex items-start gap-4">
                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shadow-md ${selectedService ? 'bg-calm-blue text-white' : 'bg-white text-slate-200'}`}>
                  {selectedService?.icon || <Video size={20} />}
                </div>
                <div>
                  <div className="font-black text-slate-900 leading-tight">{selectedService?.title || 'Selecting...'}</div>
                  <div className="text-[10px] text-slate-400 font-bold mt-1">{selectedService?.duration || 'Time TBD'}</div>
                </div>
