import React, { useState, useEffect, useMemo } from 'react';
import { X, ChevronRight, Calendar, Clock, Video, CheckCircle2, ArrowLeft, CreditCard, Download, CalendarPlus, Info, Hash, Mail, Shield, ChevronDown, Loader2, BellRing, ChevronLeft, Sun, Sunset, Moon, Sparkles, Lock, ShieldCheck, UserCheck, FileText, Share2, Globe } from 'lucide-react';
import Button from './ui/Button';
import { saveBooking } from '../utils/mockDb';

interface BookingModalProps {
  isOpen: boolean;
  onClose: () => void;
}

type Step = 'service' | 'datetime' | 'details' | 'success';
type Currency = 'USD' | 'INR';

const services = [
  { 
    id: 'individual', 
    title: 'Precision Psychotherapy', 
    duration: '50 mins', 
    priceUSD: 100, 
    priceINR: 8500,
    icon: <Video size={24} />, 
    description: 'High-fidelity CBT & ACT protocols for deep cognitive reframing.',
    code: 'CPT-90834'
  },
  { 
    id: 'couple', 
    title: 'Relationship Synchrony', 
    duration: '75 mins', 
    priceUSD: 140, 
    priceINR: 11500,
    icon: <Video size={24} />, 
    description: 'Spatial mediation techniques for high-conflict communication resolution.',
    code: 'CPT-90847'
  },
  { 
    id: 'diagnostic', 
    title: 'MindLens Bio-Review', 
    duration: '30 mins', 
    priceUSD: 65, 
    priceINR: 5500,
    icon: <Video size={24} />, 
    description: 'Clinical synthesis of your spatial assessments and AI patterns.',
    code: 'DX-REF-202'
  },
];

const timeSlots = [
  { time: '09:00 AM', period: 'morning' },
  { time: '10:30 AM', period: 'morning' },
  { time: '01:00 PM', period: 'afternoon' },
  { time: '02:30 PM', period: 'afternoon' },
  { time: '04:00 PM', period: 'afternoon' },
  { time: '05:30 PM', period: 'evening' }
];

const BookingModal: React.FC<BookingModalProps> = ({ isOpen, onClose }) => {
  const [step, setStep] = useState<Step>('service');
  const [currency, setCurrency] = useState<Currency>('USD');
  const [selectedService, setSelectedService] = useState<typeof services[0] | null>(null);
  const [selectedDate, setSelectedDate] = useState<string>('');
  const [selectedTime, setSelectedTime] = useState<string>('');
  const [formData, setFormData] = useState({ name: '', email: '', note: '' });
  const [paymentData, setPaymentData] = useState({ cardNumber: '', expiry: '', cvv: '' });
  const [confirmationId, setConfirmationId] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStatus, setProcessingStatus] = useState('');

  // Calendar State
  const [viewDate, setViewDate] = useState(new Date());

  const calendarData = useMemo(() => {
    const year = viewDate.getFullYear();
    const month = viewDate.getMonth();
    const firstDay = new Date(year, month, 1).getDay();
    const daysInMonth = new Date(year, month + 1, 0).getDate();

    const days = [];
    for (let i = 0; i < firstDay; i++) days.push(null);
    for (let i = 1; i <= daysInMonth; i++) days.push(new Date(year, month, i));

    return days;
  }, [viewDate]);

  const formattedSelectedDate = useMemo(() => {
    if (!selectedDate) return '';
    return new Date(selectedDate).toLocaleDateString('en-US', { 
      weekday: 'long', 
      month: 'long', 
      day: 'numeric' 
    });
  }, [selectedDate]);

  const getPriceDisplay = (service: typeof services[0] | null) => {
    if (!service) return '$0';
    return currency === 'USD' ? `$${service.priceUSD}` : `₹${service.priceINR.toLocaleString('en-IN')}`;
  };

  const handleDownloadReceipt = () => {
    if (!selectedService || !confirmationId) return;

    const receiptContent = `
MINDLENS CLINICAL RECEIPT
--------------------------
Confirmation ID: ${confirmationId}
Date Generated: ${new Date().toLocaleString()}
Status: COMPLETED / PAID
Clinical Facility: ML-HUB-MUMBAI-01

PATIENT DETAILS
Name: ${formData.name}
Email: ${formData.email}

SESSION DETAILS
Service: ${selectedService.title}
Clinical Code: ${selectedService.code}
Provider: Dr. Nidhi Gadoya
Scheduled Date: ${formattedSelectedDate}
Scheduled Time: ${selectedTime}
Duration: ${selectedService.duration}

PAYMENT SUMMARY
Amount Paid: ${getPriceDisplay(selectedService)}
Method: Card ending in ${paymentData.cardNumber.slice(-4)}
Currency: ${currency}
Tax Identification: GST-998399 (Placeholder)

MindLens Health Ecosystem
HIPAA SECURED DOCUMENT
--------------------------
This is an official computer-generated clinical receipt for insurance reimbursement purposes.
    `.trim();

    const blob = new Blob([receiptContent], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `MindLens-Receipt-${confirmationId}.txt`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleAddToCalendar = () => {
    if (!selectedDate || !selectedTime || !selectedService) return;

    const dateStr = new Date(selectedDate).toISOString().split('T')[0].replace(/-/g, '');
    const icsContent = `
BEGIN:VCALENDAR
VERSION:2.0
PRODID:-//MindLens//Mental Wellness App//EN
BEGIN:VEVENT
UID:${confirmationId}@mindlens.health
DTSTAMP:${new Date().toISOString().replace(/[-:]/g, '').split('.')[0]}Z
DTSTART:${dateStr}T${selectedTime.replace(/[: ]/g, '').padStart(6, '0')}
SUMMARY:MindLens Session: ${selectedService.title}
DESCRIPTION:Session with Dr. Nidhi Gadoya. Join via link in email. Confirmation: ${confirmationId}
LOCATION:MindLens Virtual Portal
END:VEVENT
END:VCALENDAR
    `.trim();

    const blob = new Blob([icsContent], { type: 'text/calendar' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `MindLens-Session-${confirmationId}.ics`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  if (!isOpen) return null;

  const handleNext = async () => {
    if (step === 'service' && selectedService) setStep('datetime');
    else if (step === 'datetime' && selectedDate && selectedTime) setStep('details');
    else if (step === 'details' && formData.name && formData.email && paymentData.cardNumber) {
      setIsProcessing(true);
      setProcessingStatus('Authorizing session gateway...');
      await new Promise(r => setTimeout(r, 1000));
      setProcessingStatus('Encrypting health tunnel...');
      await new Promise(r => setTimeout(r, 800));
      setProcessingStatus('Finalizing booking receipt...');
      await new Promise(r => setTimeout(r, 600));

      const newId = `ML-${Math.random().toString(36).substr(2, 6).toUpperCase()}`;
      setConfirmationId(newId);

      saveBooking({
        serviceId: selectedService!.id,
        serviceTitle: selectedService!.title,
        date: selectedDate,
        time: selectedTime,
        name: formData.name,
        email: formData.email,
        note: formData.note,
        amount: getPriceDisplay(selectedService!)
      });

      setIsProcessing(false);
      setStep('success');
    }
  };

  const handleBack = () => {
    if (step === 'datetime') setStep('service');
    else if (step === 'details') setStep('datetime');
  };

  const handleClose = () => {
    onClose();
    setTimeout(() => {
      setStep('service');
      setSelectedService(null);
      setSelectedDate('');
      setSelectedTime('');
      setFormData({ name: '', email: '', note: '' });
      setPaymentData({ cardNumber: '', expiry: '', cvv: '' });
      setConfirmationId('');
    }, 500);
  };

  return (
    <div className="fixed inset-0 z-[5000] flex items-center justify-center bg-slate-900/70 backdrop-blur-md animate-in fade-in duration-300">
      <div className="bg-white w-full h-full sm:h-[95vh] md:h-[90vh] lg:h-[85vh] sm:max-w-2xl lg:max-w-5xl sm:rounded-[40px] shadow-2xl overflow-hidden relative flex flex-col lg:flex-row animate-in zoom-in-95 slide-in-from-bottom-10 duration-500">

        {/* Left Interaction Flow */}
        <div className="flex-1 flex flex-col bg-white overflow-hidden relative">
          <div className="p-6 sm:p-8 border-b border-slate-100 flex items-center justify-between bg-white shrink-0 z-[60]">
            <div className="flex items-center gap-4">
              {step !== 'service' && step !== 'success' && !isProcessing && (
                <button onClick={handleBack} className="p-2.5 hover:bg-slate-50 rounded-xl text-slate-500 hover:text-slate-900 transition-all active:scale-90">
                  <ArrowLeft size={22} />
                </button>
