                         <button onClick={() => setCurrency('INR')} className={`px-4 py-2 rounded-xl text-[10px] font-black tracking-widest transition-all ${currency === 'INR' ? 'bg-white shadow-md text-calm-blue' : 'text-slate-400'}`}>INR</button>
