            <div className="p-8 space-y-8">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                  {paymentMethod === 'gpay' ? (
                    <div className="w-12 h-8 bg-black rounded-lg flex items-center justify-center">
                      <span className="text-white font-black italic text-xs">GPay</span>
                    </div>
                  ) : (
                    <SmartphoneCharging size={28} className="text-slate-900" />
                  )}
                  <h4 className="font-black text-slate-900">
                    {paymentMethod === 'gpay' ? 'Google Pay' : 'Apple Pay'}
                  </h4>
                </div>
                <button onClick={() => setShowPaymentSheet(false)} className="p-2 text-slate-400 hover:text-slate-900">
                  <X size={20} />
                </button>
              </div>

              <div className="space-y-6">
                <div className="flex justify-between items-center py-4 border-b border-slate-100">
                  <span className="text-slate-500 font-medium">Session Fee</span>
                  <span className="font-black text-slate-900 text-lg">{getPriceDisplay(selectedService)}</span>
                </div>
                <div className="flex justify-between items-center py-4 border-b border-slate-100">
                  <span className="text-slate-500 font-medium">Recipient</span>
                  <span className="font-bold text-slate-700">MindLens Health</span>
                </div>
                <div className="flex items-center gap-4 py-4">
                  <div className="w-12 h-8 bg-slate-100 rounded-md flex items-center justify-center">
                    <CreditCard size={18} className="text-slate-400" />
                  </div>
                  <div>
                    <p className="text-sm font-bold text-slate-900">Visa •••• 4242</p>
                    <p className="text-[10px] text-slate-400 font-black uppercase">{formData.email}</p>
                  </div>
                </div>
              </div>

              {sheetStatus === 'idle' ? (
                <button 
                  onClick={handleSheetConfirm}
                  className="w-full py-5 rounded-3xl bg-slate-900 text-white font-black flex items-center justify-center gap-3 active:scale-95 transition-all shadow-xl shadow-slate-900/20"
                >
                  <Fingerprint size={24} className="text-calm-blue" /> 
                  Confirm with Biometrics
                </button>
              ) : sheetStatus === 'verifying' ? (
                <div className="w-full py-5 rounded-3xl bg-slate-50 border-2 border-slate-100 flex items-center justify-center gap-3">
                   <Loader2 size={24} className="animate-spin text-calm-blue" />
