                          {['S', 'M', 'T', 'W', 'T', 'F', 'S'].map(d => <div key={d} className="text-center text-[10px] font-black text-slate-400 p-2">{d}</div>)}
                          {calendarData.map((date, idx) => {
                            const today = new Date(); today.setHours(0,0,0,0);
                            const disabled = !date || date < today;
                            const selected = date && selectedDate && new Date(selectedDate).toDateString() === date.toDateString();
                            return (
                              <button
                                key={idx}
                                disabled={disabled}
                                onClick={() => date && setSelectedDate(date.toISOString())}
                                className={`aspect-square flex items-center justify-center rounded-xl text-sm font-bold transition-all ${
                                  !date ? '' : selected ? 'bg-calm-blue text-white shadow-lg scale-110 z-10' : disabled ? 'text-slate-300' : 'text-slate-600 hover:bg-white hover:shadow-md'
                                }`}
                              >
                                {date?.getDate()}
                              </button>
                            );
                          })}
                        </div>
                      </div>
                      <div className="space-y-6">
                        {['morning', 'afternoon', 'evening'].map(period => (
                          <div key={period} className={`space-y-3 ${!selectedDate && 'opacity-30 pointer-events-none'}`}>
                            <div className="flex items-center gap-2 text-slate-400">
                              {period === 'morning' ? <Sun size={14} /> : period === 'afternoon' ? <Sunset size={14} /> : <Moon size={14} />}
                              <span className="text-[10px] font-black uppercase tracking-widest">{period}</span>
                            </div>
                            <div className="grid grid-cols-2 gap-3">
                              {timeSlots.filter(s => s.period === period).map(s => (
                                <button 
                                  key={s.time}
                                  onClick={() => setSelectedTime(s.time)}
                                  className={`p-4 rounded-2xl font-black text-sm transition-all border-2 ${
                                    selectedTime === s.time ? 'bg-calm-blue border-calm-blue text-white shadow-lg' : 'bg-white border-slate-100 text-slate-600 hover:border-blue-100'
                                  }`}
                                >
                                  {s.time}
                                </button>
                              ))}
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  </div>
                )}

                {step === 'details' && (
                  <div className="space-y-12 animate-in fade-in slide-in-from-bottom-4">
                    <div className="grid lg:grid-cols-2 gap-10">
                      <div className="space-y-6">
                        <div className="space-y-2">
                          <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Full Legal Name</label>
                          <input type="text" placeholder="Jane Doe" className="w-full p-5 bg-slate-50 border border-slate-100 rounded-2xl outline-none focus:border-calm-blue text-base font-medium" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
                        </div>
                        <div className="space-y-2">
                          <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Email ID</label>
                          <input type="email" placeholder="jane@example.com" className="w-full p-5 bg-slate-50 border border-slate-100 rounded-2xl outline-none focus:border-calm-blue text-base font-medium" value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} />
                        </div>
                        <div className="space-y-2">
                          <label className="text-[10px] font-black uppercase text-slate-400 ml-1">Intake Note</label>
                          <textarea rows={2} placeholder="Briefly describe focus areas..." className="w-full p-5 bg-slate-50 border border-slate-100 rounded-2xl outline-none focus:border-calm-blue text-base font-medium resize-none" value={formData.note} onChange={e => setFormData({...formData, note: e.target.value})} />
                        </div>
                      </div>

                      <div className="space-y-8">
                        {/* Payment Method Selector */}
                        <div className="space-y-3">
                          <label className="text-[10px] font-black uppercase text-slate-400 ml-1 tracking-widest">Select Gateway</label>
                          <div className="grid grid-cols-3 sm:grid-cols-5 gap-2">
                            <button 
                              onClick={() => setPaymentMethod('card')}
                              className={`p-3 rounded-xl border-2 transition-all flex flex-col items-center gap-1.5 ${paymentMethod === 'card' ? 'border-calm-blue bg-blue-50/50 text-calm-blue shadow-sm' : 'border-slate-100 text-slate-400 hover:border-slate-200'}`}
                            >
                              <CreditCard size={18} />
                              <span className="text-[8px] font-black uppercase">Card</span>
                            </button>
                            <button 
                              onClick={() => setPaymentMethod('bank')}
                              className={`p-3 rounded-xl border-2 transition-all flex flex-col items-center gap-1.5 ${paymentMethod === 'bank' ? 'border-calm-blue bg-blue-50/50 text-calm-blue shadow-sm' : 'border-slate-100 text-slate-400 hover:border-slate-200'}`}
                            >
                              <Building2 size={18} />
                              <span className="text-[8px] font-black uppercase">Bank</span>
                            </button>
                            <button 
                              onClick={() => setPaymentMethod('gpay')}
                              className={`p-3 rounded-xl border-2 transition-all flex flex-col items-center gap-1.5 ${paymentMethod === 'gpay' ? 'border-slate-900 bg-slate-50 text-slate-900 shadow-sm' : 'border-slate-100 text-slate-400 hover:border-slate-200'}`}
                            >
                              <Smartphone size={18} className="text-blue-500" />
                              <span className="text-[8px] font-black uppercase">GPay</span>
                            </button>
                            <button 
                              onClick={() => setPaymentMethod('apple')}
                              className={`p-3 rounded-xl border-2 transition-all flex flex-col items-center gap-1.5 ${paymentMethod === 'apple' ? 'border-slate-900 bg-slate-50 text-slate-900 shadow-sm' : 'border-slate-100 text-slate-400 hover:border-slate-200'}`}
                            >
                              <SmartphoneCharging size={18} />
                              <span className="text-[8px] font-black uppercase">Apple</span>
                            </button>
                            {currency === 'INR' && (
                              <button 
                                onClick={() => setPaymentMethod('upi')}
                                className={`p-3 rounded-xl border-2 transition-all flex flex-col items-center gap-1.5 ${paymentMethod === 'upi' ? 'border-green-600 bg-green-50/50 text-green-700 shadow-sm' : 'border-slate-100 text-slate-400 hover:border-slate-200'}`}
                              >
                                <Landmark size={18} />
                                <span className="text-[8px] font-black uppercase">UPI</span>
                              </button>
                            )}
                          </div>
                        </div>

                        <div className="relative">
                          {paymentMethod === 'card' && (
                            <div className="p-8 rounded-[40px] bg-slate-900 text-white shadow-2xl relative overflow-hidden animate-in fade-in zoom-in-95 duration-500">
                              <div className="relative z-10 space-y-6">
                                <div className="flex justify-between items-center">
                                  <CreditCard size={28} className="text-white/20" />
                                  <div className="flex gap-2">
                                    <div className="w-8 h-5 bg-white/10 rounded-sm"></div>
                                    <div className="w-8 h-5 bg-white/10 rounded-sm"></div>
                                  </div>
                                </div>
                                <div className="space-y-4">
                                  <div className="space-y-1">
                                    <label className="text-[8px] font-black uppercase tracking-widest text-white/40">16-Digit Number</label>
                                    <input type="text" placeholder="0000 0000 0000 0000" className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-lg font-mono tracking-widest outline-none focus:border-white/30" value={paymentData.cardNumber} onChange={e => setPaymentData({...paymentData, cardNumber: e.target.value})} />
                                  </div>
                                  <div className="grid grid-cols-2 gap-4">
                                    <div className="space-y-1">
                                      <label className="text-[8px] font-black uppercase tracking-widest text-white/40">Expiry</label>
                                      <input type="text" placeholder="MM/YY" className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 font-mono outline-none" value={paymentData.expiry} onChange={e => setPaymentData({...paymentData, expiry: e.target.value})} />
                                    </div>
                                    <div className="space-y-1">
                                      <label className="text-[8px] font-black uppercase tracking-widest text-white/40">Security Code</label>
                                      <input type="password" placeholder="CVV" className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 font-mono outline-none" value={paymentData.cvv} onChange={e => setPaymentData({...paymentData, cvv: e.target.value})} />
                                    </div>
                                  </div>
                                </div>
                              </div>
                            </div>
                          )}

                          {paymentMethod === 'bank' && (
                            <div className="p-8 rounded-[40px] bg-slate-50 border border-slate-100 space-y-6 animate-in fade-in zoom-in-95 duration-500">
                               <div className="flex items-center justify-between">
                                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Select Registered Bank</label>
                                  <span className="px-2 py-0.5 bg-blue-50 text-calm-blue rounded-md text-[8px] font-black">FAST TRANSFER</span>
                               </div>
                               <div className="grid grid-cols-2 gap-3">
                                  {filteredBanks.map(bank => (
                                    <button 
                                      key={bank.id}
                                      onClick={() => setPaymentData({...paymentData, selectedBankId: bank.id})}
                                      className={`p-4 rounded-2xl border-2 text-left transition-all ${
                                        paymentData.selectedBankId === bank.id ? 'border-calm-blue bg-white shadow-md' : 'border-slate-200 bg-white/50 hover:border-slate-300'
                                      }`}
                                    >
                                      <div className={`w-8 h-8 rounded-lg flex items-center justify-center text-white font-black text-xs mb-2 ${bank.color}`}>
                                        {bank.name[0]}
                                      </div>
                                      <p className="text-[10px] font-black text-slate-900 truncate">{bank.name}</p>
                                    </button>
                                  ))}
                                  <button className="p-4 rounded-2xl border-2 border-dashed border-slate-200 text-center hover:bg-slate-100 transition-colors">
                                     <p className="text-[10px] font-black text-slate-400">View All Banks</p>
                                  </button>
                               </div>
                            </div>
                          )}

                          {(paymentMethod === 'gpay' || paymentMethod === 'apple') && (
                            <div className="p-10 rounded-[40px] bg-slate-50 border-2 border-dashed border-slate-200 flex flex-col items-center justify-center text-center space-y-4 animate-in fade-in slide-in-from-bottom-4 duration-500">
                               <div className="w-16 h-16 bg-white rounded-3xl shadow-md flex items-center justify-center">
                                 {paymentMethod === 'gpay' ? <Smartphone size={32} className="text-blue-500" /> : <SmartphoneCharging size={32} />}
                               </div>
                               <div>
                                 <h5 className="font-black text-slate-900">One-Tap Checkout</h5>
                                 <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">Express {paymentMethod === 'gpay' ? 'Google' : 'Apple'} Secure Link</p>
                               </div>
                               <div className="px-4 py-1.5 bg-green-100 text-green-700 rounded-full text-[8px] font-black uppercase tracking-widest">Biometric Ready</div>
                            </div>
                          )}

                          {paymentMethod === 'upi' && (
                            <div className="p-8 rounded-[40px] bg-green-50 border border-green-100 space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
                               <div className="flex items-center gap-4">
                                 <div className="w-12 h-12 bg-white rounded-2xl shadow-sm flex items-center justify-center text-green-600">
                                   <Landmark size={24} />
                                 </div>
                                 <div>
                                   <h5 className="font-black text-green-900 leading-tight">Unified Payments</h5>
                                   <p className="text-[9px] text-green-600/60 font-black uppercase tracking-widest">Instant Settlement</p>
                                 </div>
                               </div>
                               <div className="space-y-2">
                                 <label className="text-[10px] font-black uppercase text-green-700/50 ml-1">Enter UPI ID (VPA)</label>
                                 <input 
                                   type="text" 
                                   placeholder="username@okaxis" 
                                   className="w-full px-5 py-4 bg-white border border-green-100 rounded-2xl outline-none focus:border-green-400 font-bold text-green-900" 
                                   value={paymentData.upiId} 
                                   onChange={e => setPaymentData({...paymentData, upiId: e.target.value})} 
                                 />
                               </div>
                            </div>
                          )}
                        </div>

                        <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100 flex items-center justify-center gap-6 opacity-60">
                           <div className="flex items-center gap-1.5 grayscale">
                              <Shield size={12} /> <span className="text-[8px] font-black uppercase">PCI DSS</span>
                           </div>
                           <div className="flex items-center gap-1.5 grayscale">
                              <Lock size={12} /> <span className="text-[8px] font-black uppercase">SSL 256-BIT</span>
                           </div>
                           <div className="flex items-center gap-1.5 grayscale">
                              <ShieldCheck size={12} /> <span className="text-[8px] font-black uppercase">Verified</span>
                           </div>
                        </div>
                      </div>
                    </div>
                  </div>
                )}

                {step === 'success' && (
                  <div className="text-center flex flex-col items-center justify-center h-full animate-in zoom-in">
                    <div className="w-20 h-20 bg-green-100 text-green-600 rounded-full flex items-center justify-center mb-6 shadow-inner ring-[12px] ring-green-50/50 relative">
                      <CheckCircle2 size={40} className="animate-bounce" />
                      {isEmailSending && (
                        <div className="absolute -top-2 -right-2 bg-calm-blue text-white p-2 rounded-full shadow-lg animate-in fade-in zoom-in">
                          <Loader2 size={16} className="animate-spin" />
                        </div>
                      )}
                    </div>

                    <h4 className="text-3xl font-black text-slate-900 mb-2 tracking-tight">Session Confirmed.</h4>
                    <p className="text-slate-500 font-medium mb-8">Clinical credentials verified for Dr. Nidhi Gadoya.</p>

                    <div className={`mb-8 px-6 py-3 bg-blue-50 text-calm-blue rounded-2xl flex items-center gap-3 border border-blue-100 transition-all duration-700 ${isEmailSending ? 'opacity-50 blur-[2px]' : 'opacity-100'}`}>
                      {isEmailSending ? <Loader2 size={18} className="animate-spin" /> : <Inbox size={18} />}
                      <span className="text-xs font-black uppercase tracking-widest">
                        {isEmailSending ? 'Routing Confirmation Email...' : `Sent to ${formData.email}`}
                      </span>
                    </div>

                    <div className="w-full max-w-md bg-slate-50 rounded-[40px] p-8 border border-slate-100 text-left relative overflow-hidden">
                       <div className="absolute top-0 right-0 p-4 opacity-5"><Sparkles size={100} /></div>
                       <div className="flex justify-between items-start mb-6 border-b border-slate-200 pb-6">
                         <div>
                           <div className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Conf ID</div>
                           <div className="font-mono font-black text-lg text-slate-700 tracking-widest">{confirmationId}</div>
                         </div>
                         <div className="text-right">
                            <div className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Status</div>
                            <div className="inline-flex items-center px-3 py-1 bg-green-500 text-white rounded-full text-[10px] font-black uppercase">Paid</div>
                         </div>
                       </div>

                       <div className="grid grid-cols-2 gap-8 mb-6">
                         <div>
                           <div className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Date</div>
                           <div className="font-bold text-slate-700">{new Date(selectedDate).toLocaleDateString()}</div>
                         </div>
                         <div>
                           <div className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Time</div>
                           <div className="font-bold text-slate-700">{selectedTime}</div>
                         </div>
                       </div>

                       <div className="space-y-3">
                         <button onClick={handleAddToCalendar} className="flex items-center gap-3 text-xs text-slate-600 font-bold hover:text-calm-blue transition-colors w-full group">
                           <CalendarPlus size={16} className="text-calm-blue transition-transform group-hover:scale-110" /> Add to Apple/Google Calendar
                         </button>
                         <button onClick={handleDownloadReceipt} className="flex items-center gap-3 text-xs text-slate-600 font-bold hover:text-calm-blue transition-colors w-full group">
                           <FileText size={16} className="text-calm-blue transition-transform group-hover:scale-110" /> Download Clinical Receipt
                         </button>
                         <button 
                           onClick={() => setShowEmailPreview(!showEmailPreview)}
                           className="flex items-center gap-3 text-xs text-slate-600 font-bold hover:text-calm-blue transition-colors w-full group"
                         >
                           <Mail size={16} className="text-calm-blue transition-transform group-hover:scale-110" /> 
                           {showEmailPreview ? 'Hide Email Preview' : 'View Simulated Confirmation Email'}
                         </button>
                       </div>

                       {showEmailPreview && (
                         <div className="mt-8 p-6 bg-white rounded-3xl border border-slate-200 shadow-sm animate-in slide-in-from-top-4 duration-500 overflow-hidden relative">
                           <div className="absolute top-0 right-0 p-3 opacity-5"><Inbox size={40} /></div>
                           <div className="flex items-center justify-between mb-4 pb-4 border-b border-slate-100">
                             <div className="text-[10px] font-black text-calm-blue uppercase tracking-widest">MindLens Health Support</div>
                             <div className="text-[10px] text-slate-400 font-bold">1 min ago</div>
                           </div>
                           <div className="space-y-4">
                             <p className="text-xs font-bold text-slate-900">Subject: Session Confirmation: ${selectedService?.title}</p>
                             <div className="text-[11px] text-slate-600 space-y-3 leading-relaxed">
                               <p>Hi <span className="text-slate-900 font-black">{formData.name}</span>,</p>
                               <p>Your clinical session with <span className="font-bold">Dr. Nidhi Gadoya</span> is confirmed.</p>
                               <div className="bg-slate-50 p-4 rounded-xl space-y-2 border border-slate-100 font-medium">
                                 <p><span className="font-black text-slate-400 uppercase text-[9px]">ID:</span> ${confirmationId}</p>
                                 <p><span className="font-black text-slate-400 uppercase text-[9px]">Method:</span> ${paymentMethod.toUpperCase()}</p>
                               </div>
                               <div className="bg-orange-50 p-4 rounded-xl border border-orange-100 flex gap-3">
                                 <BellRing size={16} className="text-orange-500 shrink-0" />
                                 <p className="text-orange-800 font-bold">Reminder: Final portal notification 24 hours prior to session.</p>
                               </div>
                             </div>
                           </div>
                         </div>
                       )}
                    </div>

                    <div className="mt-12 flex flex-col gap-4 w-full max-w-sm">
                       <Button variant="primary" className="py-5 rounded-2xl shadow-xl shadow-calm-blue/20" onClick={handleClose}>Done</Button>
                       <button className="text-xs font-black uppercase tracking-widest text-slate-400 hover:text-slate-600 flex items-center justify-center gap-2">
                          <Share2 size={14} /> Share Session Link
                       </button>
                    </div>
                  </div>
                )}
              </>
            )}
          </div>

          {step !== 'success' && !isProcessing && (
            <div className="p-6 sm:p-8 bg-white border-t border-slate-100 flex flex-col sm:flex-row gap-4">
              <Button 
                disabled={step === 'service' ? !selectedService : step === 'datetime' ? (!selectedDate || !selectedTime) : !isFormValid}
                className={`w-full py-5 rounded-3xl gap-3 shadow-xl transition-all text-lg font-black ${
                  paymentMethod === 'gpay' ? 'bg-slate-900 hover:bg-black' : 
                  paymentMethod === 'apple' ? 'bg-slate-900 hover:bg-black' : 
                  paymentMethod === 'upi' ? 'bg-green-600 hover:bg-green-700 shadow-green-500/20' : 
                  paymentMethod === 'bank' ? 'bg-calm-blue hover:bg-blue-800' :
                  'shadow-calm-blue/20'
                }`}
                onClick={handleNext}
              >
                {step === 'details' ? (
                  <>
                    {paymentMethod === 'card' && <><CreditCard size={22} /> Pay {getPriceDisplay(selectedService)}</>}
                    {paymentMethod === 'bank' && <><Building2 size={22} /> Pay with Net Banking</>}
                    {paymentMethod === 'gpay' && <><Smartphone size={22} className="text-blue-400" /> Pay with GPay</>}
                    {paymentMethod === 'apple' && <><SmartphoneCharging size={22} /> Pay with Apple Pay</>}
                    {paymentMethod === 'upi' && <><Landmark size={22} /> Pay with UPI</>}
                  </>
                ) : <>Next: Slot Details <ChevronRight size={22} /></>}
              </Button>
            </div>
          )}
        </div>

        {/* Desktop Summary Sidebar */}
        <div className="hidden lg:flex w-96 bg-slate-50 border-l border-slate-100 flex-col p-12 shrink-0">
          <div className="space-y-12">
            <h5 className="text-[11px] font-black uppercase text-slate-400 tracking-[0.2em]">Checkout Review</h5>

            <div className={`transition-all duration-500 ${selectedService ? 'opacity-100 translate-x-0' : 'opacity-30 translate-x-4'}`}>
              <div className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-3">Therapeutic Focus</div>
              <div className="flex items-start gap-4">
                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shadow-md ${selectedService ? 'bg-calm-blue text-white' : 'bg-white text-slate-200'}`}>
                  {selectedService?.icon || <Video size={20} />}
                </div>
                <div>
                  <div className="font-black text-slate-900 leading-tight">{selectedService?.title || 'None Selected'}</div>
                  <div className="text-[10px] text-slate-400 font-bold mt-1">{selectedService?.duration}</div>
                </div>
              </div>
            </div>

            <div className={`transition-all duration-500 delay-100 ${selectedDate ? 'opacity-100 translate-x-0' : 'opacity-30 translate-x-4'}`}>
              <div className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-3">Time Window</div>
              <div className="flex items-start gap-4">
                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shadow-md ${selectedDate ? 'bg-calm-blue text-white' : 'bg-white text-slate-200'}`}>
                  <Clock size={22} />
                </div>
                <div>
                  <div className="font-black text-slate-900 leading-tight">{selectedDate ? new Date(selectedDate).toLocaleDateString() : 'Pending'}</div>
                  <div className="text-[10px] text-calm-blue font-black mt-1 uppercase tracking-widest">{selectedTime || 'Select Slot'}</div>
                </div>
              </div>
            </div>

            <div className="pt-12 border-t border-slate-200">
               <div className="flex justify-between items-center mb-4">
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Grand Total</span>
                  <span className="text-4xl font-black text-calm-blue tracking-tighter">{getPriceDisplay(selectedService)}</span>
               </div>
               <div className="flex items-center gap-2 text-[8px] font-black text-slate-400 uppercase tracking-[0.2em]">
                 <ShieldCheck size={12} className="text-green-500" /> End-to-End Secure
               </div>
            </div>

            <div className="mt-12 space-y-4">
               <div className="p-5 bg-white rounded-3xl border border-slate-200 shadow-sm flex gap-4 items-start">
                  <Globe size={18} className="text-calm-blue shrink-0 mt-0.5" />
                  <p className="text-[10px] text-slate-500 font-medium leading-relaxed">Multimodal payments active. Local optimization for {currency === 'INR' ? 'South Asia' : 'International'} clinical protocols.</p>
               </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default BookingModal;

payload.text:
To move from a **simulation** to a **production-ready** payment system, we would transition the logic from my UI-mockups to a real Payment Gateway Integration. As a senior engineer, here is the architectural blueprint for how we execute the actual fund reception:

### 1. The Gateway Choice (The "Processor")
We don't "talk" directly to banks from the browser for security reasons (PCI-DSS compliance). Instead, we use a **Payment Aggregator** like **Stripe** (Global) or **Razorpay** (India/Asia). 
*   **Why?** They handle the encryption, vaulting of card data, and the massive complexity of connecting to thousands of different banks.

### 2. The Technical Architecture
Here is the sequence of events when a user clicks "Pay":

1.  **Payment Intent**: Our frontend sends a request to our *Backend Server* saying "User X wants to pay $100 for a Session."
2.  **The Handshake**: Our backend tells the Processor (e.g., Stripe/Razorpay) to create a "Payment Intent." The Processor returns a unique **Client Secret**.
3.  **The Checkout Sheet**: The frontend uses the **Processor's SDK** (which I've simulated in the `BookingModal`) to show the Google Pay/Apple Pay/Bank interface.
4.  **Direct Authorization**: The user authorizes the payment on their device (FaceID/Fingerprint). The data goes directly to the Processor—**MindLens never touches the bank login or card numbers.**
5.  **The Webhook (The "Proof")**: Once the bank approves, the Processor sends a **Webhook** (a secure server-to-server ping) to our backend.
6.  **Fulfillment**: Our backend receives the "Payment Succeeded" event and officially marks the booking as "Confirmed" in the database.

### 3. Receiving the Funds into Your Bank
To actually get the money into the **MindLens bank account**:
*   **Merchant Onboarding**: You would log into the Processor's Dashboard and link your business bank account (using your Routing/Account numbers or IBAN).
*   **Settlement Cycle**: The Processor usually holds funds for 24-48 hours (T+1 or T+2) and then automatically transfers the accumulated balance into your linked bank account.

### 4. Implementation Step
In the code, we would replace the `completeBookingFlow` function with a call to the SDK:

