const BookingModal: React.FC<BookingModalProps> = ({ isOpen, onClose }) => {
  const [step, setStep] = useState<Step>('service');
  const [currency, setCurrency] = useState<Currency>('USD');
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>('card');
  const [selectedService, setSelectedService] = useState<typeof services[0] | null>(null);
  const [selectedDate, setSelectedDate] = useState<string>('');
  const [selectedTime, setSelectedTime] = useState<string>('');
  const [formData, setFormData] = useState({ name: '', email: '', note: '' });
  const [paymentData, setPaymentData] = useState({ cardNumber: '', expiry: '', cvv: '', upiId: '', selectedBankId: '' });
  const [confirmationId, setConfirmationId] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStatus, setProcessingStatus] = useState('');
  const [showEmailPreview, setShowEmailPreview] = useState(false);
  const [isEmailSending, setIsEmailSending] = useState(false);

  const [showPaymentSheet, setShowPaymentSheet] = useState(false);
  const [sheetStatus, setSheetStatus] = useState<'idle' | 'verifying' | 'complete'>('idle');

  const [viewDate, setViewDate] = useState(new Date());

  const calendarData = useMemo(() => {
    const year = viewDate.getFullYear();
    const month = viewDate.getMonth();
    const firstDay = new Date(year, month, 1).getDay();
    const daysInMonth = new Date(year, month + 1, 0).getDate();

    const days = [];
    for (let i = 0; i < firstDay; i++) days.push(null);
    for (let i = 1; i <= daysInMonth; i++) days.push(new Date(year, month, i));

    return days;
  }, [viewDate]);

  const formattedSelectedDate = useMemo(() => {
    if (!selectedDate) return '';
    return new Date(selectedDate).toLocaleDateString('en-US', { 
      weekday: 'long', 
      month: 'long', 
      day: 'numeric' 
    });
  }, [selectedDate]);

  const getPriceDisplay = (service: typeof services[0] | null) => {
    if (!service) return '$0';
    return currency === 'USD' ? `$${service.priceUSD}` : `₹${service.priceINR.toLocaleString('en-IN')}`;
  };

  const isFormValid = useMemo(() => {
    if (!formData.name || !formData.email) return false;
    if (paymentMethod === 'card') {
      return paymentData.cardNumber.length >= 12 && paymentData.expiry.length >= 4 && paymentData.cvv.length >= 3;
    }
    if (paymentMethod === 'upi') return paymentData.upiId.includes('@');
    if (paymentMethod === 'bank') return !!paymentData.selectedBankId;
    return true; 
  }, [formData, paymentMethod, paymentData]);

  const completeBookingFlow = (id?: string) => {
    const newId = id || `ML-${Math.random().toString(36).substr(2, 6).toUpperCase()}`;
    setConfirmationId(newId);

    saveBooking({
      id: newId,
      serviceId: selectedService!.id,
      serviceTitle: selectedService!.title,
      date: selectedDate,
      time: selectedTime,
      name: formData.name,
      email: formData.email,
      note: formData.note,
      amount: getPriceDisplay(selectedService!),
      currency: currency,
      paymentMethod: paymentMethod.toUpperCase(),
      status: 'captured'
    });

    setIsProcessing(false);
    setStep('success');
    setIsEmailSending(true);
    setTimeout(() => setIsEmailSending(false), 2000);
  };

  const handleNext = async () => {
    if (step === 'service' && selectedService) setStep('datetime');
    else if (step === 'datetime' && selectedDate && selectedTime) setStep('details');
    else if (step === 'details' && isFormValid) {
      if (paymentMethod === 'gpay' || paymentMethod === 'apple' || paymentMethod === 'bank') {
        setSheetStatus('idle');
        setShowPaymentSheet(true);
        return;
      }

      setIsProcessing(true);
      if (paymentMethod === 'upi') setProcessingStatus('Waiting for UPI App acceptance...');
      else setProcessingStatus('Authorizing session gateway...');

      await new Promise(r => setTimeout(r, 1200));
      setProcessingStatus('Encrypting health tunnel...');
      await new Promise(r => setTimeout(r, 800));
      setProcessingStatus('Finalizing booking receipt...');
      await new Promise(r => setTimeout(r, 600));

      completeBookingFlow();
    }
  };

  const handleSheetConfirm = async () => {
    setSheetStatus('verifying');
    await new Promise(r => setTimeout(r, 1500));
    setSheetStatus('complete');
    await new Promise(r => setTimeout(r, 800));
    setShowPaymentSheet(false);
    completeBookingFlow();
  };

  const handleDownloadReceipt = () => {
    if (!selectedService || !confirmationId) return;
    const receiptContent = `MINDLENS CLINICAL RECEIPT\nConfirmation ID: ${confirmationId}\nDate: ${new Date().toLocaleString()}\nService: ${selectedService.title}\nAmount: ${getPriceDisplay(selectedService)}`;
    const blob = new Blob([receiptContent], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `MindLens-Receipt-${confirmationId}.txt`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleAddToCalendar = () => {
    if (!selectedDate || !selectedTime || !selectedService) return;
